describe('Password Authentication - Incorrect Password Error', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display error message when entering incorrect password', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in valid email and incorrect password
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call
    cy.wait('@loginRequest');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Invalid email or password');

    // Verify user is still on the login page
    cy.url().should('include', '/login');

    // Verify login form is still visible
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should not display error message when password matches', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in valid email and correct password
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('CorrectPassword123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call
    cy.wait('@loginRequest');

    // Verify error message is NOT displayed
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Login successful');
  });
});
